def transform(grid):
    from collections import Counter

    if not grid or not grid[0]:
        return grid

    n_rows = len(grid)
    n_cols = len(grid[0])

    # Find background (most common)
    bg_counts = Counter()
    for row in grid:
        bg_counts.update(row)
    bg = bg_counts.most_common(1)[0][0]

    # Find all non-background values and their positions
    objects = {}  # value -> list of (r, c) tuples
    for r in range(n_rows):
        for c in range(n_cols):
            v = grid[r][c]
            if v != bg:
                if v not in objects:
                    objects[v] = []
                objects[v].append((r, c))

    # Identify the "anchor" value = the one that starts at the bottom-right-most position
    anchor_val = None
    anchor_pos = (-1, -float('inf'))

    for v, positions in objects.items():
        if positions:
            last_r, last_c = max(positions, key=lambda x: (x[0], x[1]))
            if (last_r, last_c) > anchor_pos:
                anchor_pos = (last_r, last_c)
                anchor_val = v

    if not anchor_val:
        return [[bg] * n_cols for _ in range(n_rows)]

    # Find which columns contain anchor_val
    anchor_cols = set()
    for r, c in objects[anchor_val]:
        anchor_cols.add(c)

    sorted_cols = sorted(anchor_cols)
    out_cols = len(sorted_cols)

    # Build output: keep all values from anchor columns, reposition them
    result = [[bg] * out_cols for _ in range(n_rows)]

    for r in range(n_rows):
        for mc, orig_c in enumerate(sorted_cols):
            result[r][mc] = grid[r][orig_c]

    return result
